<template>
  <div class="sub-page-overlay" ref="overlay">
    <div class="sub-page-container">
      <div class="list-header">
        <h2 class="list-title">리스트</h2>
        <div class="filter-chips">
          <button class="chip" :class="{ on: !onlyMe }" @click="setOnlyMe(false)">전체</button>
          <button class="chip" :class="{ on: onlyMe }" @click="setOnlyMe(true)">내 당직만</button>
        </div>
      </div>

      <!-- 위로 스크롤하면 이전 달을 더 불러옴 -->
      <div ref="topSentinel" class="sentinel"></div>
      <div v-if="reachedPastEnd" class="end-marker">더 이전 일정이 없습니다.</div>

      <div
        v-for="month in visibleMonths"
        :key="month.key"
        class="month-block"
        :data-offset="month.offset"
      >
        <div class="month-label">{{ month.label }}</div>

        <div v-if="month.rows.length === 0" class="empty-row">이 달에는 등록된 당직이 없습니다.</div>

        <div
          v-for="row in month.rows"
          :key="row.dateKey"
          class="list-row"
          :class="{ 'is-me': row.isMe, 'is-today': row.isToday }"
        >
          <span class="row-date" :class="{ sun: row.dow === 0, sat: row.dow === 6 }">
            {{ row.dateLabel }}
          </span>
          <span class="row-name" :class="{ empty: !row.name }">{{ row.name || '—' }}</span>
          <span v-if="row.isToday" class="today-badge">오늘</span>
        </div>
      </div>

      <div v-if="reachedFutureEnd" class="end-marker">더 이후 일정이 없습니다.</div>
      <!-- 아래로 스크롤하면 다음 달을 더 불러옴 -->
      <div ref="bottomSentinel" class="sentinel"></div>
    </div>
  </div>
</template>

<script>
const LOAD_STEP = 3;          // 한 번에 더 불러오는 달 수
const WEEK_NAMES = ['일', '월', '화', '수', '목', '금', '토'];

// YYMMDD → 기준 달(startDate)로부터 몇 달 차이인지
function monthOffsetOf(dateKey, baseY, baseM) {
  const d = String(dateKey).padStart(6, '0');
  const y = 2000 + parseInt(d.substring(0, 2), 10);
  const m = parseInt(d.substring(2, 4), 10) - 1;
  return (y - baseY) * 12 + (m - baseM);
}

export default {
  name: 'ListPage',
  props: {
    dutyData: { type: Array, default: () => [] },
    startDate: { type: Date, default: () => new Date() }
  },
  data() {
    return {
      onlyMe: false,
      firstOffset: -1,   // 기준 달보다 1달 전부터 시작 (위로 올리면 계속 추가)
      lastOffset: LOAD_STEP - 1,
      loading: false,
      observer: null
    };
  },
  computed: {
    baseY() { return this.startDate.getFullYear(); },
    baseM() { return this.startDate.getMonth(); },

    dutyMap() {
      const map = {};
      (this.dutyData || []).forEach(p => {
        if (p.category === '당직') map[String(p.date)] = p;
      });
      return map;
    },
    // 데이터가 있는 가장 이른 / 늦은 달 (내 당직만 보기일 때는 내 당직 기준)
    dataRange() {
      const list = Object.values(this.dutyMap).filter(p => !this.onlyMe || p.meYn === 'Y');
      if (list.length === 0) return { min: 0, max: 0 };
      const offsets = list.map(p => monthOffsetOf(p.date, this.baseY, this.baseM));
      return { min: Math.min(...offsets), max: Math.max(...offsets) };
    },
    // 과거 쪽 한계: 데이터가 있는 가장 이른 달 (그보다 앞은 빈 달뿐이라 멈춤)
    minOffset() {
      return Math.min(this.onlyMe ? 0 : -1, this.dataRange.min);
    },
    // 미래 쪽 한계: 전체 보기는 제한 없음, 내 당직만은 마지막 내 당직 달까지
    maxOffset() {
      return this.onlyMe ? Math.max(0, this.dataRange.max) : Infinity;
    },
    reachedPastEnd() { return this.firstOffset <= this.minOffset; },
    reachedFutureEnd() { return this.lastOffset >= this.maxOffset; },

    months() {
      const today = new Date();
      const result = [];
      const from = Math.max(this.firstOffset, this.minOffset);
      const to = Math.min(this.lastOffset, this.maxOffset);

      for (let k = from; k <= to; k++) {
        const first = new Date(this.baseY, this.baseM + k, 1);
        const y = first.getFullYear();
        const m = first.getMonth();
        const lastDay = new Date(y, m + 1, 0).getDate();
        const rows = [];

        for (let d = 1; d <= lastDay; d++) {
          const dateKey = `${String(y).slice(-2)}${String(m + 1).padStart(2, '0')}${String(d).padStart(2, '0')}`;
          const duty = this.dutyMap[dateKey];
          const isMe = !!duty && duty.meYn === 'Y';
          if (this.onlyMe && !isMe) continue;

          const dow = new Date(y, m, d).getDay();
          rows.push({
            dateKey,
            dateLabel: `${m + 1}/${d} (${WEEK_NAMES[dow]})`,
            dow,
            name: duty ? duty.name : '',
            isMe,
            isToday: y === today.getFullYear() && m === today.getMonth() && d === today.getDate()
          });
        }

        result.push({ key: `${y}-${m}`, offset: k, label: `${y}년 ${m + 1}월`, rows });
      }
      return result;
    },
    // 내 당직만 보기일 때는 내 당직이 없는 달을 숨김 (기준 달은 항상 표시)
    visibleMonths() {
      if (!this.onlyMe) return this.months;
      return this.months.filter(mo => mo.rows.length > 0 || mo.offset === 0);
    }
  },
  mounted() {
    this.$nextTick(() => {
      this.scrollToStart();
      this.observer = new IntersectionObserver(this.onIntersect, {
        root: this.$refs.overlay,
        rootMargin: '400px 0px'
      });
      // 첫 위치를 잡은 다음에 감시 시작 (처음부터 위쪽이 불러와지는 것 방지)
      requestAnimationFrame(() => {
        this.observer.observe(this.$refs.topSentinel);
        this.observer.observe(this.$refs.bottomSentinel);
      });
    });
  },
  beforeUnmount() {
    if (this.observer) this.observer.disconnect();
  },
  methods: {
    // 오늘이 보이면 오늘 줄, 아니면 기준 달 제목으로 이동
    scrollToStart() {
      const overlay = this.$refs.overlay;
      if (!overlay) return;
      const today = overlay.querySelector('.is-today');
      const startBlock = overlay.querySelector('.month-block[data-offset="0"]');
      const todayInStart = today && startBlock && startBlock.contains(today);
      if (todayInStart) {
        today.scrollIntoView({ block: 'center' });
      } else if (startBlock) {
        overlay.scrollTop = startBlock.offsetTop - 8;
      }
    },
    onIntersect(entries) {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        if (entry.target === this.$refs.topSentinel) this.loadPast();
        else if (entry.target === this.$refs.bottomSentinel) this.loadFuture();
      });
    },
    loadFuture() {
      if (this.loading || this.reachedFutureEnd) return;
      this.loading = true;
      this.lastOffset += LOAD_STEP;
      this.$nextTick(() => {
        this.loading = false;
        this.recheckSentinel(this.$refs.bottomSentinel, this.loadFuture);
      });
    },
    loadPast() {
      if (this.loading || this.reachedPastEnd) return;
      const overlay = this.$refs.overlay;
      this.loading = true;
      const prevHeight = overlay.scrollHeight;
      const prevTop = overlay.scrollTop;
      this.firstOffset -= LOAD_STEP;
      this.$nextTick(() => {
        // 위에 내용이 붙은 만큼 스크롤 위치를 내려서 보던 자리 유지
        overlay.scrollTop = prevTop + (overlay.scrollHeight - prevHeight);
        this.loading = false;
        this.recheckSentinel(this.$refs.topSentinel, this.loadPast);
      });
    },
    // 불러온 뒤에도 감시 지점이 화면 근처에 남아 있으면 한 번 더 불러옴
    recheckSentinel(el, loader) {
      const overlay = this.$refs.overlay;
      if (!el || !overlay) return;
      const r = el.getBoundingClientRect();
      const o = overlay.getBoundingClientRect();
      if (r.bottom > o.top - 400 && r.top < o.bottom + 400) {
        requestAnimationFrame(loader);
      }
    },
    setOnlyMe(value) {
      if (this.onlyMe === value) return;
      this.onlyMe = value;
      this.firstOffset = -1;
      this.lastOffset = LOAD_STEP - 1;
      this.$nextTick(() => this.scrollToStart());
    }
  }
};
</script>

<style scoped>
.sub-page-overlay {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: #f9f9f9; z-index: 3000; /* 하단바(5000)보다 낮게 */
  overflow-y: auto;
  overflow-anchor: none; /* 위로 불러올 때 스크롤 위치는 직접 맞춤 */
  -webkit-overflow-scrolling: touch;
}
.sub-page-container {
  max-width: 600px; margin: 0 auto;
  padding: max(env(safe-area-inset-top), 12px) 14px 130px;
  text-align: left;
}
.list-header { display: flex; justify-content: space-between; align-items: center; padding: 0 6px 6px; }
.list-title { font-size: 1.8rem; font-weight: bold; color: #333; margin: 6px 0; }
.filter-chips { display: flex; gap: 6px; }
.chip {
  font-size: 0.8rem; padding: 5px 12px; border-radius: 14px; border: 1px solid #ddd;
  background: #fff; color: #555; cursor: pointer;
}
.chip.on { background: #e3f2fd; color: #1976d2; border-color: #90caf9; font-weight: bold; }

.sentinel { height: 1px; }
.end-marker { text-align: center; font-size: 0.8rem; color: #aaa; padding: 14px 0; }

.month-block { margin-bottom: 6px; }
/* 스크롤 중에도 지금 보고 있는 달이 위에 고정되어 보임 */
.month-label {
  position: sticky; top: 0; z-index: 1;
  background: #f9f9f9;
  font-size: 0.9rem; font-weight: bold; color: #1976d2; padding: 12px 6px 6px;
}

.list-row {
  display: flex; align-items: center; background: #fff; border-bottom: 1px solid #f1f1f1;
  padding: 10px 12px; font-size: 0.95rem;
}
.row-date { width: 88px; flex-shrink: 0; color: #444; font-weight: bold; }
.row-date.sun { color: #f44336; }
.row-date.sat { color: #2196F3; }
.row-name { flex: 1; color: #222; }
.row-name.empty { color: #bbb; }
.list-row.is-me { background: #e3f2fd; }
.list-row.is-me .row-name { color: #1976d2; font-weight: bold; }
.list-row.is-today { border-left: 4px solid #ec2525; padding-left: 8px; }
.today-badge {
  font-size: 0.7rem; color: #ec2525; border: 1px solid #f5b5b5; border-radius: 8px; padding: 1px 6px; margin-left: 6px;
}
.empty-row { padding: 14px 12px; font-size: 0.85rem; color: #aaa; background: #fff; }
</style>
