<template>
  <div class="calendar-container">
    <!-- ===== 달력 영역 (70%) ===== -->
    <div class="calendar-section">
      <div class="header-top">
        <h1 class="month-title">{{ currentMonthTitle }}</h1>
        <div class="header-bottom">
          <label for="startDay">시작 요일:</label>
          <select id="startDay" v-model="startDayIndex">
            <option value="0">일요일</option>
            <option value="1">월요일</option>
          </select>
          <button @click="requestNotificationPermission" class="noti-permission-btn" title="알림 설정">🔔</button>
        </div>
      </div>

      <div class="weekdays">
        <span
          v-for="day in reorderedWeekdays"
          :key="day"
          :class="{'sunday': day === '일', 'saturday': day === '토'}"
        >
          {{ day }}
        </span>
      </div>

      <!-- 좌우 스와이프로 달을 넘기는 영역 (이전달 / 현재달 / 다음달 3장을 나란히 두고 이동) -->
      <div
        ref="swipeViewport"
        class="swipe-viewport"
        @pointerdown="onPointerDown"
        @pointermove="onPointerMove"
        @pointerup="onPointerUp"
        @pointercancel="onPointerCancel"
        @dragstart.prevent
        @contextmenu.prevent
      >
        <div class="swipe-track" :style="trackStyle">
          <div v-for="(panel, pi) in monthPanels" :key="panel.key" class="swipe-panel">
            <div class="days">
              <!-- 클릭(@click)은 쓰지 않고, 움직임 없이 짧게 눌렀다 뗐을 때만 탭으로 처리 -->
              <span
                v-for="day in panel.days"
                :key="day.key"
                :data-key="pi === 1 ? day.key : null"
                :class="{
                  'day': true,
                  'padded': day.padded,
                  'today': day.isToday,
                  'my-duty': getDutyName(day.dateKey) && getDutyName(day.dateKey).isMe,
                  'pressed': pi === 1 && pressedKey === day.key,
                  'is-selected': pi === 1 && popover.key === 'c-' + day.key
                }"
              >
                {{ day.number }}
                <!-- 2줄까지 보여주고 넘치면 ".." (v-clamp 가 글자를 직접 잘라 넣음) -->
                <div
                  v-if="getDutyName(day.dateKey)"
                  class="duty-name"
                  v-clamp="getDutyName(day.dateKey).name"
                ></div>
              </span>
            </div>
          </div>
        </div>
      </div>

      <div class="swipe-hint">
        <button class="hint-btn" @click="prevMonth">‹ {{ prevMonthLabel }}</button>
        <span class="hint-dots"><b></b><b class="on"></b><b></b></span>
        <button class="hint-btn" @click="nextMonth">{{ nextMonthLabel }} ›</button>
      </div>
    </div>

    <!-- ===== 미래 일정 타임라인 (30%) ===== -->
    <div ref="timelineEl" class="future-timeline">
      <!-- 글자 폭 측정용 (화면에는 안 보임) -->
      <span ref="fontProbe" class="timeline-row timeline-probe" aria-hidden="true">가</span>

      <div v-if="timelineColumns.length === 0" class="timeline-empty">
        이후 등록된 당직이 없습니다.
      </div>
      <div v-else ref="timelineScroller" class="timeline-scroller" @scroll="closePopover">
        <div v-for="(col, ci) in timelineColumns" :key="'col-' + ci" class="timeline-col">
          <div
            v-for="row in col"
            :key="row.key"
            :class="{
              'timeline-row': true,
              'timeline-item': row.type === 'item',
              'timeline-month': row.type === 'month',
              'timeline-cont': row.type === 'cont',
              'is-selected': row.type === 'item' && popover.key === 't-' + row.key
            }"
            @click="row.type === 'item' && openTimelinePopover(row, $event)"
          >
            <template v-if="row.type === 'item'">
              <span class="timeline-date">{{ row.dateLabel }}</span>
              <span class="timeline-name" :class="{ 'is-me': row.isMe }" v-clamp="row.name"></span>
            </template>
            <template v-else>
              <span class="timeline-dot"></span>{{ row.label }}
            </template>
          </div>
        </div>
      </div>
    </div>

    <!-- 전체 내용 말풍선 -->
    <div
      v-if="popover.visible"
      ref="popoverEl"
      class="detail-popover"
      :class="popover.placement"
      :style="{ top: popover.top + 'px', left: popover.left + 'px', '--arrow-x': popover.arrowX + 'px' }"
    >
      <div class="popover-date">{{ popover.dateText }}</div>
      <div class="popover-content">{{ popover.content }}</div>
    </div>

    <div v-if="updateExists" class="update-notification">
      <p>새로운 버전 발견! 업데이트하시겠습니까?</p>
      <button @click="refreshApp">업데이트</button>
    </div>

    <div v-if="showPasswordModal" class="modal-overlay">
      <div class="modal-content">
        <h3>비밀번호 확인</h3>
        <p>당직 정보를 수정/입력하려면 비밀번호를 입력하세요.</p>
        <input type="password" v-model="passwordInput" @keyup.enter="validatePassword" placeholder="비밀번호" autofocus>
        <div class="modal-buttons">
          <button @click="validatePassword" class="modal-confirm">확인</button>
          <button @click="cancelPassword" class="modal-cancel">취소</button>
        </div>
        <p v-if="passwordMessage" class="error-message">{{ passwordMessage }}</p>
      </div>
    </div>

    <div v-if="showEditForm" class="edit-form-container">
      <h2>{{ formDocId ? '당직 정보 수정' : '새 당직 정보 입력' }} ({{ currentEditingDate }})</h2>

      <div class="form-grid">
        <label for="category">Category:</label>
        <input id="category" type="text" v-model="formEntry.category">

        <label for="holidayYn">Holiday (Y/N):</label>
        <select id="holidayYn" v-model="formEntry.holidayYn">
          <option value="Y">Y</option>
          <option value="N">N</option>
        </select>

        <label for="meYn">Me (Y/N):</label>
        <select id="meYn" v-model="formEntry.meYn">
          <option value="Y">Y</option>
          <option value="N">N</option>
        </select>

        <label for="name">Name:</label>
        <input id="name" type="text" v-model="formEntry.name">

        <label for="changeReason">변경 사유:</label>
        <input
          id="changeReason"
          type="text"
          v-model="formEntry.changeReason"
          placeholder="사유 입력"
        >

        <label for="sendNoti">알림 여부:</label>
        <input id="sendNoti" type="checkbox" v-model="formEntry.sendNotification" style="width: 20px; height: 20px;">

        <div class="form-buttons">
          <button @click="saveDuty" class="save-button">저장</button>
          <button @click="closeForm" class="cancel-button">취소</button>
          <button @click="goToSetting" class="setting-button">설정</button>
        </div>
      </div>
      <p v-if="formMessage" :class="{'error-message': formError, 'success-message': !formError}">
        {{ formMessage }}
      </p>
    </div>
  </div>
</template>

<script>
// 타임라인 줄 높이(px) - CSS .timeline-row / .timeline-item 과 맞춰야 함
const TIMELINE_ROW_HEIGHT = 20;        // 월 제목, 1줄짜리 일정
const TIMELINE_LINE_HEIGHT = 15;       // 일정 글자 줄 간격
const TIMELINE_ITEM_PADDING = 5;       // 일정 위아래 여백 합
const TIMELINE_DATE_GAP = 5;           // 날짜와 이름 사이 간격
const CLAMP_LINES = 2;                 // 몇 줄까지 보여줄지
const CLAMP_SUFFIX = '..';             // 넘칠 때 붙일 글자

/* ---------------------------------------------------------
   v-clamp: 글자를 CLAMP_LINES 줄까지만 넣고 넘치면 ".." 을 붙임
   (CSS line-clamp 는 "…" 만 붙일 수 있어서 직접 자름)
   --------------------------------------------------------- */
function clampElement(el) {
  const full = el.__clampText == null ? '' : String(el.__clampText);
  el.textContent = full;
  el.title = full;
  if (!full || el.clientWidth === 0) return; // 숨겨진 상태면 보일 때 다시 처리

  const style = window.getComputedStyle(el);
  let lineHeight = parseFloat(style.lineHeight);
  if (isNaN(lineHeight)) lineHeight = parseFloat(style.fontSize) * 1.2;
  const maxHeight = lineHeight * CLAMP_LINES + 1;
  if (el.scrollHeight <= maxHeight) return;

  // 들어가는 가장 긴 길이를 이분 탐색
  let lo = 0;
  let hi = full.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    el.textContent = full.slice(0, mid).trimEnd() + CLAMP_SUFFIX;
    if (el.scrollHeight <= maxHeight) lo = mid;
    else hi = mid - 1;
  }
  el.textContent = full.slice(0, lo).trimEnd() + CLAMP_SUFFIX;
}

let clampObserver = null;
function getClampObserver() {
  if (!clampObserver && window.ResizeObserver) {
    clampObserver = new ResizeObserver(entries => {
      entries.forEach(entry => {
        const el = entry.target;
        const w = Math.round(entry.contentRect.width);
        if (el.__clampWidth !== w) {   // 폭이 바뀌었을 때만 다시 자름
          el.__clampWidth = w;
          clampElement(el);
        }
      });
    });
  }
  return clampObserver;
}

const clampDirective = {
  mounted(el, binding) {
    el.__clampText = binding.value;
    clampElement(el);
    const ob = getClampObserver();
    if (ob) ob.observe(el);
  },
  updated(el, binding) {
    if (binding.value !== binding.oldValue || el.textContent === '') {
      el.__clampText = binding.value;
      clampElement(el);
    }
  },
  beforeUnmount(el) {
    if (clampObserver) clampObserver.unobserve(el);
  }
};

// 일정 줄 높이 계산용 글자 폭 측정기
let measureCanvas = null;
function measureTextWidth(text, font) {
  if (!measureCanvas) measureCanvas = document.createElement('canvas');
  const ctx = measureCanvas.getContext ? measureCanvas.getContext('2d') : null;
  if (!ctx) {
    // canvas 를 못 쓰는 환경: 글자 수 x 글자 크기로 대략 계산
    const size = parseFloat((font.match(/([\d.]+)px/) || [])[1]) || 12.5;
    return String(text).length * size;
  }
  ctx.font = font;
  return ctx.measureText(text).width;
}
const SWIPE_THRESHOLD = 0.18;     // 화면 폭의 18% 이상 밀면 달이 넘어감
const SWIPE_DECIDE_PX = 8;        // 이만큼 움직이면 탭이 아니라 밀기로 판단
const SWIPE_ANIM_MS = 280;
const PRESS_DELAY_MS = 90;        // 이 시간 동안 움직이지 않아야 회색 눌림 표시 (밀기 시작할 때 깜빡임 방지)
const TAP_MAX_MS = 600;           // 이보다 오래 누르면 탭으로 보지 않음
const TAP_FLASH_MS = 150;         // 빠르게 탭했을 때 회색을 보여주는 시간

export default {
  name: 'HelloWorld',
  directives: { clamp: clampDirective },
  props: {
    dutyData: {
      type: Array,
      default: () => []
    },
    saveDutyEntry: {
      type: Function,
      required: true
    },
    checkPassword: {
      type: Function,
      required: true
    }
  },
  data() {
    return {
      weekdays: ['일', '월', '화', '수', '목', '금', '토'],
      currentDate: new Date(),
      startDayIndex: parseInt(localStorage.getItem('startDayIndex')) || 0,
      updateExists: false,
      registration: null,

      lastTaps: [],
      editingDay: null,
      currentEditingDate: '',
      formDocId: null,

      showPasswordModal: false,
      passwordInput: '',
      passwordMessage: '',

      showEditForm: false,
      formEntry: {
        category: '당직',
        date: '',
        holidayYn: 'N',
        meYn: 'N',
        name: '',
        sendNotification: true
      },
      formMessage: '',
      formError: false,

      // 스와이프 상태
      dragX: 0,
      swipeAnimating: false,
      pointerStart: null,
      swipeDirection: null,   // null | 'h' | 'v'

      // 탭(눌림) 상태
      pressedKey: null,       // 회색으로 표시할 날짜 칸
      tapCandidate: null,     // { key, time } 눌렀지만 아직 탭인지 밀기인지 모르는 상태
      pressTimer: null,
      flashTimer: null,

      // 타임라인 한 열에 들어가는 줄 수 (화면 높이를 재서 계산)
      timelineHeight: 160,     // 타임라인 안쪽 높이(px)
      timelineColInner: 90,    // 한 열에서 글자가 들어가는 폭(px)
      timelineFont: '12.5px sans-serif',
      timelineFontBold: 'bold 12.5px sans-serif',
      resizeObserver: null,

      // 전체 내용 말풍선
      popover: {
        visible: false,
        key: null,
        dateText: '',
        content: '',
        top: 0,
        left: 0,
        arrowX: 0,
        placement: 'up'
      }
    };
  },
  computed: {
    currentMonthTitle() {
      const year = this.currentDate.getFullYear();
      const month = this.currentDate.getMonth();
      return `${year}년 ${month + 1}월`;
    },
    prevMonthLabel() {
      const d = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() - 1, 1);
      return `${d.getMonth() + 1}월`;
    },
    nextMonthLabel() {
      const d = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() + 1, 1);
      return `${d.getMonth() + 1}월`;
    },
    reorderedWeekdays() {
      const days = [...this.weekdays];
      for (let i = 0; i < this.startDayIndex; i++) {
        days.push(days.shift());
      }
      return days;
    },
    daysInCurrentMonth() {
      return this.buildDays(this.currentDate.getFullYear(), this.currentDate.getMonth());
    },
    // 스와이프용 3장: 이전달 / 현재달 / 다음달
    monthPanels() {
      const y = this.currentDate.getFullYear();
      const m = this.currentDate.getMonth();
      return [-1, 0, 1].map(offset => {
        const d = new Date(y, m + offset, 1);
        return {
          key: `${d.getFullYear()}-${d.getMonth()}`,
          days: offset === 0 ? this.daysInCurrentMonth : this.buildDays(d.getFullYear(), d.getMonth())
        };
      });
    },
    trackStyle() {
      return {
        transform: `translateX(calc(-33.3333% + ${this.dragX}px))`,
        transition: this.swipeAnimating ? `transform ${SWIPE_ANIM_MS}ms ease-out` : 'none'
      };
    },
    // 달력 마지막 칸 이후의 당직을 월별로 묶어서 반환
    futureTimeline() {
      if (!this.dutyData || this.dutyData.length === 0) return [];

      const days = this.daysInCurrentMonth;
      const lastKey = parseInt(days[days.length - 1].dateKey, 10);
      const viewYear = this.currentDate.getFullYear();
      const weekNames = ['일', '월', '화', '수', '목', '금', '토'];

      const future = this.dutyData
        .filter(p => p.category === '당직' && parseInt(p.date, 10) > lastKey)
        .sort((a, b) => parseInt(a.date, 10) - parseInt(b.date, 10));

      const groups = [];
      future.forEach(p => {
        const d = String(p.date).padStart(6, '0');
        const year = 2000 + parseInt(d.substring(0, 2), 10);
        const month = parseInt(d.substring(2, 4), 10);
        const day = parseInt(d.substring(4, 6), 10);
        const groupKey = `${year}-${month}`;

        let group = groups[groups.length - 1];
        if (!group || group.key !== groupKey) {
          group = {
            key: groupKey,
            label: year === viewYear ? `${month}월` : `${year}년 ${month}월`,
            items: []
          };
          groups.push(group);
        }

        const dow = weekNames[new Date(year, month - 1, day).getDay()];
        group.items.push({
          id: p.id,
          dateLabel: `${month}/${day}(${dow})`,
          fullDate: `${year}년 ${month}월 ${day}일 (${dow})`,
          name: p.name,
          isMe: p.meYn === 'Y'
        });
      });

      return groups;
    },
    // 타임라인을 위→아래로 채우고, 열 높이가 차면 다음 열로 넘기기
    // (이름이 길어 2줄이 되는 일정은 그만큼 높이를 더 차지)
    timelineColumns() {
      const cap = Math.max(this.timelineHeight, TIMELINE_ROW_HEIGHT * 3);
      const cols = [[]];
      let cur = cols[0];
      let used = 0;
      const newCol = () => { cur = []; cols.push(cur); used = 0; };

      this.futureTimeline.forEach(group => {
        const firstItemH = group.items.length ? this.timelineItemHeight(group.items[0]) : 0;
        // 월 제목이 열 맨 아래에 혼자 남지 않도록 첫 일정과 함께 들어갈 자리가 없으면 다음 열로
        if (cur.length > 0 && used + TIMELINE_ROW_HEIGHT + firstItemH > cap) newCol();
        cur.push({ type: 'month', key: `${group.key}-h`, label: group.label });
        used += TIMELINE_ROW_HEIGHT;

        group.items.forEach(item => {
          const h = this.timelineItemHeight(item);
          if (used + h > cap) {
            newCol();
            cur.push({ type: 'cont', key: `${group.key}-c${cols.length}`, label: `${group.label} 이어서` });
            used += TIMELINE_ROW_HEIGHT;
          }
          cur.push({ type: 'item', key: item.id, ...item });
          used += h;
        });
      });

      return cols[0].length > 0 ? cols : [];
    }
  },
  watch: {
    startDayIndex(newVal) {
      localStorage.setItem('startDayIndex', newVal);
    }
  },
  created() {
    document.addEventListener('swUpdated', this.showUpdatePrompt, { once: true });
  },
  mounted() {
    document.addEventListener('pointerdown', this.onDocumentPointerDown, true);
    window.addEventListener('resize', this.closePopover);
    this.measureTimeline();
    if (window.ResizeObserver && this.$refs.timelineEl) {
      this.resizeObserver = new ResizeObserver(() => { this.measureTimeline(); this.closePopover(); });
      this.resizeObserver.observe(this.$refs.timelineEl);
    } else {
      window.addEventListener('resize', this.measureTimeline);
    }
  },
  beforeUnmount() {
    clearTimeout(this.pressTimer);
    clearTimeout(this.flashTimer);
    document.removeEventListener('pointerdown', this.onDocumentPointerDown, true);
    window.removeEventListener('resize', this.closePopover);
    if (this.resizeObserver) this.resizeObserver.disconnect();
    window.removeEventListener('resize', this.measureTimeline);
  },
  methods: {
    // 특정 연/월의 달력 칸(앞뒤 흐린 칸 포함) 만들기
    buildDays(year, month) {
      const today = new Date();
      const days = [];

      const firstDayOfMonth = new Date(year, month, 1).getDay();
      const firstDayWithOffset = (firstDayOfMonth - this.startDayIndex + 7) % 7;

      // 지난 달 날짜
      const prevDate = new Date(year, month, 0);
      const daysInPrevMonth = prevDate.getDate();
      const prevMonthYear = prevDate.getFullYear();
      const prevMonth = prevDate.getMonth() + 1;

      for (let i = 0; i < firstDayWithOffset; i++) {
        const dayNumber = daysInPrevMonth - firstDayWithOffset + 1 + i;
        const dateKey = this.formatDate(prevMonthYear, prevMonth, dayNumber);
        days.push({ key: `prev-${dateKey}`, number: dayNumber, padded: true, isToday: false, dateKey });
      }

      // 현재 달 날짜
      const daysInMonth = new Date(year, month + 1, 0).getDate();
      for (let j = 1; j <= daysInMonth; j++) {
        const isToday = new Date(year, month, j).toDateString() === today.toDateString();
        const dateKey = this.formatDate(year, month + 1, j);
        days.push({ key: `current-${dateKey}`, number: j, padded: false, isToday, dateKey });
      }

      // 다음 달 날짜 (마지막 주를 채움)
      const nextDate = new Date(year, month + 1, 1);
      const nextMonthYear = nextDate.getFullYear();
      const nextMonth = nextDate.getMonth() + 1;
      let nextDayNumber = 1;
      while (days.length < 42 && days.length % 7 !== 0) {
        const dateKey = this.formatDate(nextMonthYear, nextMonth, nextDayNumber);
        days.push({ key: `next-${dateKey}`, number: nextDayNumber, padded: true, isToday: false, dateKey });
        nextDayNumber++;
      }

      return days;
    },

    // 타임라인 영역의 높이·열 폭·글꼴을 재서 열 나누기에 사용
    measureTimeline() {
      const el = this.$refs.timelineEl;
      if (!el || el.clientHeight === 0) return; // v-show로 숨겨져 있을 때는 건너뜀
      const style = window.getComputedStyle(el);
      this.timelineHeight = el.clientHeight - parseFloat(style.paddingTop) - parseFloat(style.paddingBottom);

      // 스크롤 영역 좌우 여백(10 + 22), 열 사이 간격(10 x 2), 열 안쪽(테두리 2 + 여백 9)
      const contentWidth = el.clientWidth - 32;
      this.timelineColInner = (contentWidth - 20) / 3 - 11;

      const probe = this.$refs.fontProbe;
      if (probe) {
        const ps = window.getComputedStyle(probe);
        this.timelineFont = `${ps.fontWeight} ${ps.fontSize} ${ps.fontFamily}`;
        this.timelineFontBold = `bold ${ps.fontSize} ${ps.fontFamily}`;
      }
    },
    // 일정 한 줄의 높이: 날짜 + 이름이 한 줄에 들어가면 1줄, 아니면 2줄(최대)
    timelineItemHeight(item) {
      const dateW = measureTextWidth(item.dateLabel, this.timelineFont);
      const nameW = measureTextWidth(item.name || '', item.isMe ? this.timelineFontBold : this.timelineFont);
      const nameRoom = this.timelineColInner - dateW - TIMELINE_DATE_GAP;
      const lines = nameW <= nameRoom ? 1 : CLAMP_LINES;
      return lines === 1 ? TIMELINE_ROW_HEIGHT : TIMELINE_LINE_HEIGHT * lines + TIMELINE_ITEM_PADDING;
    },

    // ----- 말풍선 -----
    openPopoverAt(el, key, dateText, content) {
      if (!el) return;
      const rect = el.getBoundingClientRect();
      this.popover = {
        visible: true, key, dateText, content,
        top: -9999, left: -9999, arrowX: 0, placement: 'up'
      };
      // 크기를 잰 다음 위치 결정 (위에 자리가 있으면 위, 없으면 아래)
      this.$nextTick(() => {
        const pop = this.$refs.popoverEl;
        if (!pop) return;
        const pw = pop.offsetWidth;
        const ph = pop.offsetHeight;
        const vw = window.innerWidth;
        const centerX = rect.left + rect.width / 2;
        const left = Math.min(Math.max(8, centerX - pw / 2), vw - pw - 8);
        const up = rect.top - ph - 10 > 8;
        this.popover.left = left;
        this.popover.top = up ? rect.top - ph - 8 : rect.bottom + 8;
        this.popover.arrowX = Math.min(Math.max(14, centerX - left), pw - 14);
        this.popover.placement = up ? 'up' : 'down';
      });
    },
    openDayPopover(day) {
      const duty = this.getDutyName(day.dateKey);
      if (!duty) { this.closePopover(); return; }
      const cell = this.$refs.swipeViewport && this.$refs.swipeViewport.querySelector(`.day[data-key="${day.key}"]`);
      const d = this.currentDate;
      const dow = this.weekdays[new Date(d.getFullYear(), d.getMonth(), day.number).getDay()];
      const dateText = `${d.getFullYear()}년 ${d.getMonth() + 1}월 ${day.number}일 (${dow})`;
      this.openPopoverAt(cell, `c-${day.key}`, dateText, duty.name);
    },
    openTimelinePopover(row, event) {
      const key = `t-${row.key}`;
      if (this.popover.visible && this.popover.key === key) { this.closePopover(); return; }
      this.openPopoverAt(event.currentTarget, key, row.fullDate, row.name);
    },
    closePopover() {
      if (this.popover.visible) this.popover = { ...this.popover, visible: false, key: null };
    },
    // 말풍선 바깥을 누르면 닫기
    onDocumentPointerDown(e) {
      if (!this.popover.visible) return;
      const pop = this.$refs.popoverEl;
      if (pop && pop.contains(e.target)) return;
      // 같은 칸/일정을 다시 누르는 경우는 각 핸들러에서 처리
      if (e.target.closest && e.target.closest('.timeline-item, .day[data-key]:not(.padded)')) return;
      this.closePopover();
    },

    // ----- 스와이프 -----
    // 터치(PWA)와 마우스(데스크톱 모드)를 모두 pointer 이벤트로 처리
    onPointerDown(e) {
      if (this.swipeAnimating) return;
      if (e.pointerType === 'mouse' && e.button !== 0) return; // 마우스는 왼쪽 버튼만
      if (this.pointerStart) return;                           // 두 번째 손가락은 무시

      this.pointerStart = { x: e.clientX, y: e.clientY, id: e.pointerId };
      this.swipeDirection = null;
      this.cancelPress();

      // 현재 달의 날짜 칸을 눌렀으면 탭 후보로 기억
      const cell = e.target && e.target.closest ? e.target.closest('.day[data-key]') : null;
      if (cell && !cell.classList.contains('padded')) {
        const key = cell.dataset.key;
        this.tapCandidate = { key, time: Date.now() };
        // 잠깐 기다렸다가도 움직이지 않으면 그때 회색 표시
        this.pressTimer = setTimeout(() => {
          if (this.tapCandidate && this.tapCandidate.key === key && this.swipeDirection === null) {
            this.pressedKey = key;
          }
        }, PRESS_DELAY_MS);
      }
    },
    onPointerMove(e) {
      if (!this.pointerStart || e.pointerId !== this.pointerStart.id) return;
      const dx = e.clientX - this.pointerStart.x;
      const dy = e.clientY - this.pointerStart.y;

      if (this.swipeDirection === null) {
        if (Math.abs(dx) < SWIPE_DECIDE_PX && Math.abs(dy) < SWIPE_DECIDE_PX) return;
        // 조금이라도 움직였으면 탭이 아님 → 회색 표시와 탭 후보 취소
        this.cancelPress();
        this.closePopover();
        this.swipeDirection = Math.abs(dx) > Math.abs(dy) ? 'h' : 'v';
        if (this.swipeDirection === 'h') {
          try { this.$refs.swipeViewport.setPointerCapture(this.pointerStart.id); } catch (err) { /* 무시 */ }
        }
      }
      if (this.swipeDirection === 'h') {
        this.dragX = dx;
      }
    },
    onPointerUp(e) {
      if (!this.pointerStart || (e && e.pointerId !== this.pointerStart.id)) return;
      const direction = this.swipeDirection;
      const tap = this.tapCandidate;
      this.pointerStart = null;
      this.swipeDirection = null;

      if (direction === 'h') {
        this.finishSwipe();
      } else if (direction === null && tap && Date.now() - tap.time < TAP_MAX_MS) {
        // 움직임 없이 눌렀다 뗐을 때만 탭
        this.cancelPress();
        this.flashPressed(tap.key);
        const day = this.daysInCurrentMonth.find(d => d.key === tap.key);
        if (day) {
          this.handleDayClick(day);
          // 세 번째 탭으로 비밀번호 창이 열렸으면 말풍선은 닫고, 아니면 전체 내용 말풍선 표시
          if (this.showPasswordModal) this.closePopover();
          else this.openDayPopover(day);
        }
        return;
      }
      this.cancelPress();
    },
    // 브라우저가 세로 스크롤 등으로 터치를 가져갔을 때
    onPointerCancel(e) {
      if (!this.pointerStart || (e && e.pointerId !== this.pointerStart.id)) return;
      const direction = this.swipeDirection;
      this.pointerStart = null;
      this.swipeDirection = null;
      this.cancelPress();
      if (direction === 'h') this.finishSwipe();
    },
    finishSwipe() {
      const width = this.$refs.swipeViewport.clientWidth || 1;
      if (Math.abs(this.dragX) > width * SWIPE_THRESHOLD) {
        this.slideTo(this.dragX < 0 ? 1 : -1);
      } else {
        this.swipeAnimating = true;
        this.dragX = 0;
        setTimeout(() => { this.swipeAnimating = false; }, SWIPE_ANIM_MS);
      }
    },
    cancelPress() {
      clearTimeout(this.pressTimer);
      this.pressTimer = null;
      this.tapCandidate = null;
      if (!this.flashTimer) this.pressedKey = null;
    },
    // 탭한 칸을 잠깐 회색으로 보여주기
    flashPressed(key) {
      clearTimeout(this.flashTimer);
      this.pressedKey = key;
      this.flashTimer = setTimeout(() => {
        this.pressedKey = null;
        this.flashTimer = null;
      }, TAP_FLASH_MS);
    },
    slideTo(dir) {
      this.closePopover();
      const width = this.$refs.swipeViewport.clientWidth || 0;
      this.swipeAnimating = true;
      this.dragX = dir > 0 ? -width : width;
      setTimeout(() => {
        this.swipeAnimating = false;
        this.dragX = 0;
        this.currentDate = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() + dir, 1);
        this.closeForm();
      }, SWIPE_ANIM_MS);
    },

    // App.vue의 "이동" 창에서 호출
    goToMonth(year, month) {
      this.closePopover();
      this.currentDate = new Date(year, month - 1, 1);
      this.closeForm();
    },

    async requestNotificationPermission() {
      try {
        const permission = await Notification.requestPermission();
        if (permission === 'granted') {
          alert('알림 권한이 허용되었습니다! 이제 당직 업데이트 알림을 받으실 수 있습니다.');
          window.location.reload();
        } else if (permission === 'denied') {
          alert('알림 권한이 거부되었습니다. 설정에서 알림을 허용해주세요.');
        }
      } catch (error) {
        console.error('알림 권한 요청 중 오류:', error);
        alert('이 브라우저에서는 알림 기능을 지원하지 않거나 오류가 발생했습니다.');
      }
    },
    async saveDuty() {
      this.formMessage = '저장 중...';
      this.formError = false;

      const isSuccess = await this.saveDutyEntry(this.formEntry, this.formDocId);

      if (isSuccess) {
        this.formMessage = '성공적으로 저장되었습니다.';
        setTimeout(() => {
          this.closeForm();
        }, 500);
      } else {
        this.formMessage = '저장에 실패했습니다.';
        this.formError = true;
      }
    },
    formatDate(year, month, day) {
      const yearFormatted = String(year).slice(-2);
      const monthFormatted = String(month).padStart(2, '0');
      const dayFormatted = String(day).padStart(2, '0');
      return `${yearFormatted}${monthFormatted}${dayFormatted}`;
    },
    goToSetting() {
      this.closeForm();
      this.$emit('open-setting');
    },
    getDutyName(dateKey) {
      if (!dateKey || !this.dutyData) return null;

      const dutyPerson = this.dutyData.find(person =>
        person.date === dateKey && person.category === '당직'
      );

      if (dutyPerson) {
        return {
          name: dutyPerson.name,
          isMe: dutyPerson.meYn === 'Y',
          docId: dutyPerson.id,
          fullEntry: dutyPerson
        };
      }
      return null;
    },

    handleDayClick(day) {
      if (day.padded) return;

      const now = Date.now();
      const dateKey = day.dateKey;

      this.lastTaps = this.lastTaps.filter(time => now - time < 500);
      this.lastTaps.push(now);

      if (this.lastTaps.length === 3) {
        this.editingDay = day.number;
        this.currentEditingDate = dateKey;
        this.showPasswordModal = true;
        this.passwordInput = '';
        this.passwordMessage = '';
        this.lastTaps = [];
      }
    },

    async validatePassword() {
      this.passwordMessage = '확인 중...';
      const result = await this.checkPassword(this.passwordInput);

      if (result.success) {
        this.passwordMessage = '';
        this.showPasswordModal = false;
        this.openEditForm();
      } else {
        this.passwordMessage = result.message || "비밀번호가 올바르지 않습니다.";
      }
    },

    cancelPassword() {
      this.showPasswordModal = false;
      this.passwordInput = '';
      this.passwordMessage = '';
    },

    openEditForm() {
      const dutyEntry = this.getDutyName(this.currentEditingDate);

      this.formEntry.date = this.currentEditingDate;
      this.formMessage = '';
      this.formError = false;

      if (dutyEntry && dutyEntry.fullEntry) {
        const entry = dutyEntry.fullEntry;
        this.formDocId = entry.id;
        this.formEntry.category = entry.category;
        this.formEntry.holidayYn = entry.holidayYn;
        this.formEntry.meYn = entry.meYn;
        this.formEntry.name = entry.name;
      } else {
        this.formDocId = null;
        this.formEntry.category = '당직';
        this.formEntry.holidayYn = 'N';
        this.formEntry.meYn = 'N';
        this.formEntry.name = '';
      }
      this.formEntry.sendNotification = true;
      this.showEditForm = true;
    },

    closeForm() {
      this.showEditForm = false;
      this.editingDay = null;
      this.currentEditingDate = '';
      this.formDocId = null;
      this.formMessage = '';
      this.formError = false;
      this.formEntry = { category: '당직', date: '', holidayYn: 'N', meYn: 'N', name: '', sendNotification: true, changeReason: '' };
    },

    prevMonth() {
      if (this.swipeAnimating) return;
      this.slideTo(-1);
    },
    nextMonth() {
      if (this.swipeAnimating) return;
      this.slideTo(1);
    },
    showUpdatePrompt(event) {
      this.registration = event.detail;
      this.updateExists = true;
    },
    refreshApp() {
      this.updateExists = false;
      if (this.registration && this.registration.waiting) {
        this.registration.waiting.postMessage({ type: 'SKIP_WAITING' });
      }
      window.location.reload();
    }
  }
};
</script>

